it('removes outputs older than max age when not in active set', async () => {
  const storage = getStorageManager();

  // Store two outputs
  await storage.storeOutput(100, new Uint8Array([1, 2, 3, 4]), 'test-100.dat', 'application/octet-stream');
  // Manually set createdAt to 25 hours ago for this test
  const metadata100 = await storage.getOutputMetadata(100);
  if (metadata100) {
    (metadata100 as any).createdAt = Date.now() - (25 * 60 * 60 * 1000);
  }

  await storage.storeOutput(200, new Uint8Array([5, 6, 7, 8]), 'test-200.dat', 'application/octet-stream');
  // Keep this one recent (1 hour old)
  const metadata200 = await storage.getOutputMetadata(200);
  if (metadata200) {
    (metadata200 as any).createdAt = Date.now() - (1 * 60 * 60 * 1000);
  }

  const activeIds = new Set<number>(); // No active sessions

  const cleaned = await storage.cleanupOrphanedOutputs(activeIds);

  expect(cleaned).toBe(1);
  const remaining = await storage.listOutputs();
  expect(remaining).toHaveLength(1);
  expect(remaining[0].streamId).toBe(200);
});

